export type Conexao = 'INTERNET_SEGURA' | 'RECONECTANDO' | 'SOMENTE_LEITURA_DESATUALIZADA' | 'SEM_CONEXAO';
export type Sessao = { id: string; name?: string; type?: string; state?: string; startedAt?: number | null; competitors: { kart?: string; name?: string }[]; sessionRevision: number };
export type EventoEstado = { seq: number; sessoes: Sessao[] };
export type EstadoTempoReal = { conexao: Conexao; sessoes: Sessao[]; ultimoSeq: number; escritaLiberada: boolean; precisaSincronizar: boolean; aguardandoCompleto: boolean; atualizadoEm: number | null };

export const estadoInicial: EstadoTempoReal = { conexao: 'SEM_CONEXAO', sessoes: [], ultimoSeq: 0, escritaLiberada: false, precisaSincronizar: false, aguardandoCompleto: true, atualizadoEm: null };

/** Cada conexão recomeça a sequência; o primeiro evento dela é sempre o estado completo. */
export const aoConectar = (e: EstadoTempoReal): EstadoTempoReal => ({ ...e, ultimoSeq: 0, escritaLiberada: false, aguardandoCompleto: true });
export const aoDesconectar = (e: EstadoTempoReal): EstadoTempoReal => ({ ...e, conexao: 'RECONECTANDO', escritaLiberada: false, aguardandoCompleto: true });
export const aoVoltarDoFundo = (e: EstadoTempoReal): EstadoTempoReal => ({ ...e, escritaLiberada: false, precisaSincronizar: true, aguardandoCompleto: true });

export function aplicarEvento(e: EstadoTempoReal, ev: EventoEstado): EstadoTempoReal {
  if (ev.seq <= e.ultimoSeq) return e;
  if (!e.aguardandoCompleto && ev.seq !== e.ultimoSeq + 1) return { ...e, precisaSincronizar: true, escritaLiberada: false, aguardandoCompleto: true };
  const anteriores = new Map(e.sessoes.map((s) => [s.id, s]));
  const sessoes = ev.sessoes.map((s) => {
    const a = anteriores.get(s.id);
    return a && a.sessionRevision > s.sessionRevision ? a : s;
  });
  return { conexao: 'INTERNET_SEGURA', sessoes, ultimoSeq: ev.seq, escritaLiberada: true, precisaSincronizar: false, aguardandoCompleto: false, atualizadoEm: Date.now() };
}
